/**
 * Apply Filter to Image
 */
private void applyFilter(PhotoFilter filterType) {
    try {
        mPhotoEditor = buildPhotoEditor();
        mPhotoEditor.setFilterEffect(filterType);
        mFilterName = filterType.name();
        if (filterType != PhotoFilter.NONE) {
            mUnsavedChanges = true;
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

/**
 * Creates a photo editor for the current view and keeps track of the
 * modifications (doodles) performed through it.
 *
 * @return the newly created photo editor
 */
private PhotoEditor buildPhotoEditor() {
    PhotoEditor photoEditor = new PhotoEditor.Builder(this, mPhotoEditorView)
            .setPinchTextScalable(true)
            .build();
    photoEditor.setOnPhotoEditorListener(mPhotoEditorListener);
    return photoEditor;
}

