207	        mImgcount.setText(sText);
208	    }
209	
210	    /**
211	     * Saves Current Image with applied filter
212	     */
213	    private void saveCurrentImage() {
214	        try {
215	            File sdCard = Environment.getExternalStorageDirectory();
216	            File dir = new File(sdCard.getAbsolutePath() + "/PDFfilter");
217	            dir.mkdirs();
218	            String fileName = String.format(getString(R.string.filter_file_name),
219	                    String.valueOf(System.currentTimeMillis()), mFilterName);
220	            File outFile = new File(dir, fileName);
221	            String imagePath = outFile.getAbsolutePath();
222	
223	            mPhotoEditor.saveAsFile(imagePath, new PhotoEditor.OnSaveListener() {
224	                @Override
225	                public void onSuccess(@NonNull String imagePath) {
226	                    mImagepaths.remove(mCurrentImage);
227	                    mImagepaths.add(mCurrentImage, imagePath);
228	                    mPhotoEditorView.getSource()
229	                            .setImageBitmap(BitmapFactory.decodeFile(mImagepaths.get(mCurrentImage)));
230	                    Toast.makeText(getApplicationContext(), R.string.filter_saved, Toast.LENGTH_SHORT).show();
231	                }
232	
233	                @Override
234	                public void onFailure(@NonNull Exception exception) {
235	                    Toast.makeText(getApplicationContext(), R.string.filter_not_saved, Toast.LENGTH_SHORT).show();
236	                }
237	            });
238	        } catch (SecurityException e) {
239	            e.printStackTrace();
240	        }
241	    }
242	
243	
244	    /**
245	     * Intent to Send Back final edited URIs
246	     *
247	     * @param mImagepaths - the images array to be send pack
248	     */
249	    private void passUris(ArrayList<String> mImagepaths) {
250	        Intent returnIntent = new Intent();
251	        returnIntent.putStringArrayListExtra(RESULT, mImagepaths);
252	        setResult(Activity.RESULT_OK, returnIntent);
253	        finish();
254	    }
255	
256	    /**
257	     * Display next image on nextImage button click
258	     */
259	    private void next() {
260	        try {
261	            if (mCurrentImage + 1 <= mImagesCount) {
262	                mPhotoEditorView.getSource()
263	                        .setImageBitmap(BitmapFactory.decodeFile(mImagepaths.get(mCurrentImage + 1)));
264	                mCurrentImage++;
265	            }
266	        } catch (Exception e) {
267	            e.printStackTrace();
268	        }
269	    }
270	
271	    /**
272	     * Display Previous image on previousImage button click
273	     */
274	    private void previous() {
275	        try {
276	            if (mCurrentImage - 1 >= 0) {
277	                mPhotoEditorView.getSource()
278	                        .setImageBitmap(BitmapFactory.decodeFile(mImagepaths.get((mCurrentImage - 1))));
279	                mCurrentImage--;
280	            }
281	        } catch (Exception e) {
282	            e.printStackTrace();
283	        }
