286	    /**
287	     * Initialize Recycler View
288	     */
289	    private void initRecyclerView() {
290	        LinearLayoutManager layoutManager = new LinearLayoutManager(this, LinearLayoutManager.HORIZONTAL, false);
291	        RecyclerView recyclerView = findViewById(R.id.recyclerView);
292	        recyclerView.setLayoutManager(layoutManager);
293	        ImageFiltersAdapter adapter = new ImageFiltersAdapter(mFilterItems, this, this);
294	        recyclerView.setAdapter(adapter);
295	
296	        LinearLayoutManager layoutManager2 = new LinearLayoutManager(this, LinearLayoutManager.HORIZONTAL, false);
297	        brushColorsView.setLayoutManager(layoutManager2);
298	        BrushItemAdapter brushItemAdapter = new BrushItemAdapter(this,
299	                this, mBrushItems);
300	        brushColorsView.setAdapter(brushItemAdapter);
301	    }
302	
303	    /**
304	     * Get Item Position and call Filter Function
305	     *
306	     * @param view     - view which is clicked
307	     * @param position - position of item clicked
308	     */
309	    @Override
310	    public void onItemClick(View view, int position) {
311	        // Brush effect is in second position
312	        if (position == 1) {
313	            mPhotoEditor = new PhotoEditor.Builder(this, mPhotoEditorView)
314	                    .setPinchTextScalable(true)
315	                    .build();
316	            if (doodleSeekBar.getVisibility() == View.GONE && brushColorsView.getVisibility() == View.GONE) {
317	                mPhotoEditor.setBrushDrawingMode(true);
318	                doodleSeekBar.setVisibility(View.VISIBLE);
319	                brushColorsView.setVisibility(View.VISIBLE);
320	                mDoodleSelected = true;
321	            } else if (doodleSeekBar.getVisibility() == View.VISIBLE &&
322	                    brushColorsView.getVisibility() == View.VISIBLE) {
323	                mPhotoEditor.setBrushDrawingMode(false);
324	                doodleSeekBar.setVisibility(View.GONE);
325	                brushColorsView.setVisibility(View.GONE);
326	            }
327	        } else {
328	            PhotoFilter filter = mFilterItems.get(position).getFilter();
329	            applyFilter(filter);
330	        }
331	    }
332	
333	    /**
334	     * Apply Filter to Image
335	     */
336	    private void applyFilter(PhotoFilter filterType) {
337	        try {
338	            mPhotoEditor = new PhotoEditor.Builder(this, mPhotoEditorView)
339	                    .setPinchTextScalable(true)
340	                    .build();
341	            mPhotoEditor.setFilterEffect(filterType);
342	            mFilterName = filterType.name();
343	            mClickedFilter = filterType != PhotoFilter.NONE;
344	        } catch (Exception e) {
345	            e.printStackTrace();
346	        }
347	    }
348	
349	    @Override
350	    public boolean onCreateOptionsMenu(Menu menu) {
351	        MenuInflater menuInflater = getMenuInflater();
352	        menuInflater.inflate(R.menu.activity_filter_menu, menu);
353	        return true;
354	    }
355	
356	    @Override
357	    public boolean onOptionsItemSelected(MenuItem item) {
358	        switch (item.getItemId()) {
359	            case R.id.finish:
360	                passUris(mImagepaths);
361	                return true;
362	            case android.R.id.home:
363	                new MaterialDialog.Builder(this)
364	                        .onPositive((dialog, which) -> finish())
365	                        .title(R.string.filter_cancel_question)
366	                        .content(R.string.filter_cancel_description)
367	                        .positiveText(R.string.ok)
368	                        .negativeText(R.string.cancel).show();
369	                return true;
370	            default:
371	                return super.onOptionsItemSelected(item);
372	        }
373	    }
374	
375	    @Override
376	    public void onBackPressed() {
377	        passUris(mImagepaths);
378	    }
