381	    public void onItemClick(int position) {
382	        int color = mBrushItems.get(position).getColor();
383	        doodleSeekBar.setBackgroundColor(getResources().getColor(color));
384	        mPhotoEditor.setBrushColor(getResources().getColor(color));
385	    }
